# THE ONKELOS ROWS of Deuteronomy 12:17-31 (THE DEUTERONOMY WALK sitting 10 — CHAPTER 12, 2026-09-20; the one run): not in your gates, before the LORD
# with the household and the Levite, the border enlarged, the slaughter as commanded, the gazelle and the hart, the blood is the life, the holy things carried,
# the altar, observe and hear, the nations cut off, the snare, the abomination. The cuts by ch12_ink.HP / AP. Chapter 11's form (ch11_rows_onkelos_b.py).
from ch12_ink import *
R = {}
def row(c, v, verdict, prose): R[(c, v)] = (verdict, prose)

row(12, 17, 'MATERIAL', f'YOU MAY NOT EAT WITHIN YOUR GATES THE TITHE OF YOUR GRAIN, YOUR WINE AND YOUR OIL, OR THE FIRSTLINGS OF YOUR HERD AND YOUR FLOCK, OR ANY OF YOUR VOWS WHICH YOU VOW, OR YOUR FREEWILL OFFERINGS, OR THE HEAVE OFFERING OF YOUR HAND. {HP(12, 17, (("לא", "תוכל", "לאכל", "בשעריך"), "you may not eat within your gates — \'may not\' the book\'s eight; not able, not permitted (72:1)"), (("מעשר", "דגנך", "ותירשך", "ויצהרך"), "the tithe of your grain, wine and oil — one seat; the tithe STARRED by the parser (the ten-word)"), (("ובכרת", "בקרך", "וצאנך"), "and the firstlings of your herd and flock — 14:23 the kin"))} {AP(12, 17, (("לית", "לך", "רשו", "למיכל"), "you have NO PERMISSION to eat — the Aramaic\'s reading is the Sifrei\'s"))} The third list; the five prohibitions by the ladder of a fortiori (72:9-74:1).')
row(12, 18, 'MATERIAL', f'BUT BEFORE THE LORD YOUR GOD YOU SHALL EAT IT, IN THE PLACE WHICH THE LORD YOUR GOD WILL CHOOSE — YOU AND YOUR SON AND YOUR DAUGHTER, YOUR MANSERVANT AND YOUR MAIDSERVANT, AND THE LEVITE WITHIN YOUR GATES — AND YOU SHALL REJOICE BEFORE THE LORD YOUR GOD IN ALL THAT YOU PUT YOUR HAND TO. {HP(12, 18, (("כי", "אם", "לפני", "יהוה", "אלהיך", "תאכלנו"), "but before the LORD your God you shall eat it — one seat; Shiloh and Jerusalem (74:2-3)"), (("אתה", "ובנך", "ובתך", "ועבדך", "ואמתך"), "you and your son and daughter, manservant and maidservant — THE SABBATH\'S LIST (5:14), 16:11, 14"), (("והלוי", "אשר", "בשעריך"), "and the Levite within your gates — 14:27, 16:11"))} {AP(12, 18, (("ותחדי", "קדם", "יי", "אלהך"), "and you shall rejoice before the LORD your God"))} Thirteen tokens shared with 16:11 in order — the chapter\'s closest kin in the book (computed); twelve singular suffixes, the chapter\'s most.')
row(12, 19, 'MATERIAL', f'TAKE HEED TO YOURSELF LEST YOU FORSAKE THE LEVITE ALL YOUR DAYS ON YOUR LAND. {HP(12, 19, (("פן", "תעזב", "את", "הלוי"), "lest you forsake the Levite — one seat; THE VERSE SHARES TWO TOKENS WITH NO VERSE OF THE BIBLE"), (("כל", "ימיך", "על", "אדמתך"), "all your days on your land — even sabbaticals and jubilees, not in the exile (74:8-9)"))} {AP(12, 19, (("דילמא", "תשבוק", "ית", "לואי"), "lest you forsake the Levite"))} The second "take heed" a prohibition (74:6-7).')
row(12, 20, 'MATERIAL', f'WHEN THE LORD YOUR GOD ENLARGES YOUR BORDER, AS HE HAS SPOKEN TO YOU, AND YOU SAY: LET ME EAT FLESH — FOR YOUR SOUL CRAVES TO EAT FLESH — WITH ALL THE DESIRE OF YOUR SOUL YOU MAY EAT FLESH. {HP(12, 20, (("כי", "ירחיב", "יהוה", "אלהיך", "את", "גבולך"), "when the LORD your God enlarges your border — one seat plene; 19:8 defective, Exodus 34:24 the promise"), (("כאשר", "דבר", "לך"), "AS HE HAS SPOKEN TO YOU — the AS_WHEN form, four in the book; Genesis 15 or Ezekiel 48 (75:2)"), (("ואמרת", "אכלה", "בשר"), "and you say: let me eat flesh — the eater\'s \'I\'; flesh four times in the verse"), (("כי", "תאוה", "נפשך"), "for your soul craves — the quails\' verb (Numbers 11:4, 34) and the tenth word\'s (5:21)"))} {AP(12, 20, (("כמא", "די", "מליל", "לך"), "as He spoke to you — the Aramaic\'s four seats the Hebrew\'s four"))} The flesh of desire released (75:3) or the verse\'s own commandments (75:4).')
row(12, 21, 'MATERIAL', f'WHEN THE PLACE WHICH THE LORD YOUR GOD WILL CHOOSE TO PUT HIS NAME THERE IS TOO FAR FROM YOU, YOU SHALL SLAUGHTER OF YOUR HERD AND OF YOUR FLOCK WHICH THE LORD HAS GIVEN YOU, AS I HAVE COMMANDED YOU, AND EAT WITHIN YOUR GATES WITH ALL THE DESIRE OF YOUR SOUL. {HP(12, 21, (("כי", "ירחק", "ממך", "המקום"), "when the place is too far from you — 14:24 the kin (twelve tokens shared)"), (("וזבחת", "מבקרך", "ומצאנך"), "you shall slaughter OF your herd and OF your flock — the partitive (75:5)"), (("כאשר", "צויתך"), "AS I HAVE COMMANDED YOU — THE RECEIPT WITHOUT THE NAME: Exodus 23:15 its one kin; the finder blind to it"), (("ואכלת", "בשעריך"), "and eat within your gates — one seat"))} {AP(12, 21, (("כמא", "די", "פקדתך"), "as I commanded you — the Aramaic\'s one seat"))} The slaughter\'s rite the callee (75:6), the gullet and the windpipe (75:15).')
row(12, 22, 'MATERIAL', f'BUT AS THE GAZELLE AND THE HART ARE EATEN, SO YOU SHALL EAT IT; THE UNCLEAN AND THE CLEAN TOGETHER MAY EAT IT. {HP(12, 22, (("אך", "כאשר", "יאכל", "את", "הצבי", "ואת", "האיל"), "but as the gazelle and the hart are eaten — \'but\' the chapter\'s one; the pair with the article one seat"), (("הטמא", "והטהור", "יחדו", "יאכלנו"), "the unclean and the clean together may eat it — one dish, not the heave offering (75:11)"))} {AP(12, 22, (("כמא", "די", "מתאכל", "בשר", "טביא"), "as the FLESH of the gazelle is eaten — supplied again"))} The comparison that teaches and is taught (75:15).')
row(12, 23, 'MATERIAL', f'ONLY BE STEADFAST NOT TO EAT THE BLOOD, FOR THE BLOOD IS THE LIFE, AND YOU SHALL NOT EAT THE LIFE WITH THE FLESH. {HP(12, 23, (("רק", "חזק", "לבלתי", "אכל", "הדם"), "only be steadfast not to eat the blood — \'be strong\' the word said to Joshua (1:38, 31:7, 23)"), (("כי", "הדם", "הוא", "הנפש"), "for the blood is the life — Leviticus 17:11\'s clause turned; Genesis 9:4 shares nothing"), (("ולא", "תאכל", "הנפש", "עם", "הבשר"), "and you shall not eat the life with the flesh — the limb from the living (76:5)"))} {AP(12, 23, (("ארי", "דמא", "הוא", "נפשא"), "for the blood is the life"))} Steeped in blood before Sinai (76:1); the lightest commandment (76:2).')
row(12, 24, 'CONTEXT', f'YOU SHALL NOT EAT IT; ON THE EARTH YOU SHALL POUR IT LIKE WATER. {HP(12, 24, (("לא", "תאכלנו"), "you shall not eat it — 12:24-25 the pair; flesh in milk included (76:7)"))} {AP(12, 24, (("לא", "תיכלניה"), "you shall not eat it"))} 12:16\'s clause repeated in the singular.')
row(12, 25, 'MATERIAL', f'YOU SHALL NOT EAT IT, THAT IT MAY GO WELL WITH YOU AND WITH YOUR CHILDREN AFTER YOU, WHEN YOU DO WHAT IS RIGHT IN THE EYES OF THE LORD. {HP(12, 25, (("למען", "ייטב", "לך", "ולבניך", "אחריך"), "that it may go well with you and your children after you — 12:28 the one kin"), (("כי", "תעשה", "הישר", "בעיני", "יהוה"), "when you do what is right in the eyes of the LORD — 21:9 the kin; twenty-one seats of the phrase"))} {AP(12, 25, (("ארי", "תעבד", "דכשר", "קדם", "יי"), "when you do what is FIT before the LORD"))} The third \'you shall not eat it\' in a row (23, 24, 25).')
row(12, 26, 'MATERIAL', f'ONLY YOUR HOLY THINGS WHICH YOU HAVE, AND YOUR VOWS, YOU SHALL TAKE UP AND GO TO THE PLACE WHICH THE LORD WILL CHOOSE. {HP(12, 26, (("רק", "קדשיך", "אשר", "יהיו", "לך"), "only your holy things which you have — \'your holy things\' the Bible\'s one seat"), (("תשא", "ובאת", "אל", "המקום"), "you shall take up and go to the place — one seat"))} {AP(12, 26, (("לחוד", "מעשר", "קודשיך"), "only THE TITHE of your holy things — SUPPLIED: the Aramaic names the second tithe"))} From abroad (77:1) or the substitute (77:6, 78:9).')
row(12, 27, 'MATERIAL', f'AND YOU SHALL OFFER YOUR BURNT OFFERINGS, THE FLESH AND THE BLOOD, ON THE ALTAR OF THE LORD YOUR GOD; AND THE BLOOD OF YOUR SACRIFICES SHALL BE POURED ON THE ALTAR OF THE LORD YOUR GOD, AND THE FLESH YOU SHALL EAT. {HP(12, 27, (("ועשית", "עלתיך", "הבשר", "והדם"), "you shall offer your burnt offerings, the flesh and the blood — no blood no flesh (78:1-2)"), (("ודם", "זבחיך", "ישפך"), "and the blood of your sacrifices shall be poured — the sin offering\'s verb (Leviticus 4:7, 18, 25, 30, 34)"), (("מזבח", "יהוה", "אלהיך"), "the altar of the LORD your God — twice here, 16:21, 26:4, 27:6"))} {AP(12, 27, (("ודם", "נכסת", "קודשיך", "ישתפך"), "and the blood of your holy sacrifices shall be poured"))} The base and the one pouring (78:6); the substitute follows (78:10).')
row(12, 28, 'MATERIAL', f'OBSERVE AND HEAR ALL THESE WORDS WHICH I COMMAND YOU, THAT IT MAY GO WELL WITH YOU AND WITH YOUR CHILDREN AFTER YOU FOREVER, WHEN YOU DO THE GOOD AND THE RIGHT IN THE EYES OF THE LORD YOUR GOD. {HP(12, 28, (("שמר", "ושמעת"), "observe and hear — the imperative + perfect, one seat; the ladder of learning (79:1)"), (("עד", "עולם"), "forever — the book\'s four"), (("הטוב", "והישר"), "the good and the right — 6:18\'s pair; Heaven\'s eyes and man\'s (79:5)"))} {AP(12, 28, (("טר", "ותקבל"), "keep and RECEIVE — \'hear\' made accept"), (("דתקן", "ודכשר", "קדם", "יי"), "what is proper and fit before the LORD"))} 4:40 the closest kin (ten tokens).')
row(12, 29, 'MATERIAL', f'WHEN THE LORD YOUR GOD CUTS OFF THE NATIONS WHITHER YOU GO TO DISPOSSESS THEM FROM BEFORE YOU, AND YOU DISPOSSESS THEM AND DWELL IN THEIR LAND — {HP(12, 29, (("כי", "יכרית", "יהוה", "אלהיך", "את", "הגוים"), "when the LORD your God cuts off the nations — 19:1 the twin (eight tokens)"), (("וירשת", "אתם", "וישבת", "בארצם"), "and you dispossess them and dwell in their land — build anywhere (80:3)"))} {AP(12, 29, (("ארי", "ישצי", "יי", "אלהך", "ית", "עממיא"), "when the LORD your God destroys the nations"))} The reward conditional (80:1-2); the sages at the border (80:4-5).')
row(12, 30, 'MATERIAL', f'TAKE HEED TO YOURSELF LEST YOU BE ENSNARED AFTER THEM, AFTER THEY ARE DESTROYED FROM BEFORE YOU, AND LEST YOU INQUIRE AFTER THEIR GODS, SAYING: HOW DID THESE NATIONS SERVE THEIR GODS? AND I WILL DO SO TOO. {HP(12, 30, (("פן", "תנקש", "אחריהם"), "lest you be ensnared after them — the root\'s one Torah seat; 7:25\'s snare another root"), (("ופן", "תדרש", "לאלהיהם"), "and lest you inquire after their gods — 12:5\'s verb of seeking"), (("לאמר", "איכה", "יעבדו", "הגוים", "האלה"), "saying: how did these nations serve — the chapter\'s one \'saying\', the seeker\'s speech"), (("ואעשה", "כן", "גם", "אני"), "and I will do so, I too — the toga and the purple (81:4)"))} {AP(12, 30, (("דילמא", "תתקל", "בתריהון"), "lest you stumble after them"), (("ואעבד", "כן", "אף", "אנא"), "and I will do so, I too"))} The third \'take heed\' (81:1).')
row(12, 31, 'MATERIAL', f'YOU SHALL NOT DO SO TO THE LORD YOUR GOD, FOR EVERY ABOMINATION OF THE LORD WHICH HE HATES THEY DID FOR THEIR GODS; FOR EVEN THEIR SONS AND THEIR DAUGHTERS THEY BURN IN THE FIRE TO THEIR GODS. {HP(12, 31, (("לא", "תעשה", "כן", "ליהוה", "אלהיך"), "you shall not do so to the LORD your God — 12:4\'s pair, singular; the wrong altar (81:5)"), (("כל", "תועבת", "יהוה", "אשר", "שנא"), "every abomination of the LORD which He hates — \'which He hates\' 16:22 the one kin"), (("בניהם", "ואת", "בנתיהם", "ישרפו", "באש"), "their sons and daughters they burn in the fire — Jeremiah 7:31 the closest (six tokens); no Molech named"))} {AP(12, 31, (("כל", "דמרחק", "קדם", "יי"), "all that is DISTANCED before the LORD — the abomination\'s Aramaic"), (("יוקדין", "בנורא", "לטעותהון"), "they burn in fire to their errors"))} The parents included (81:6).')

assert sorted(R) == [(12, v) for v in range(17, 32)], sorted(R)
